package org.magora.node

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.time.Instant
import java.time.OffsetDateTime

class TemporalTest {

    /**
     * temporal_vectors.tsv was generated by running get_time_category and
     * get_temporal_context copied verbatim from detect.py at f0c1940 on astral 3.2
     * (the version the node image pins), for 8 sites and 5,958 timestamps, including a
     * dense sweep at the phone site (29.4607, -103.655) across UTC midnight.
     */
    @Test
    fun matchesDetectPyOnAstralVectors() {
        val lines = javaClass.classLoader!!.getResourceAsStream("temporal_vectors.tsv")!!
            .bufferedReader().readLines().filter { it.isNotBlank() }
        assertTrue(lines.size > 5000)
        val mismatches = mutableListOf<String>()
        var nullCases = 0
        for (line in lines) {
            val f = line.split('\t')
            val lat = f[0].toDouble()
            val lon = f[1].toDouble()
            val now = OffsetDateTime.parse(f[2]).toInstant()
            val got = Temporal.context(now, lat, lon)
            val expected = listOf(f[3], f[4], f[5], f[6], f[7])
            val actual = listOf(
                got.timeCategory,
                got.minutesFromSunrise?.toString() ?: "None",
                got.dawnChorusWindow?.let { if (it) "True" else "False" } ?: "None",
                got.phenologicalWeek?.toString() ?: "None",
                got.season ?: "None",
            )
            if (expected[1] == "None") nullCases++
            if (expected != actual) mismatches += "$line -> $actual"
        }
        assertTrue("expected some astral-failure cases in the vectors", nullCases > 0)
        assertEquals(mismatches.take(10).joinToString("\n"), 0, mismatches.size)
    }

    @Test
    fun week48MatchesBirdnetlib() {
        // Values from birdnetlib.utils.return_week_48_from_datetime.
        val cases = mapOf(
            "2026-01-01" to 1, "2026-01-08" to 2, "2026-02-28" to 8, "2026-11-05" to 41,
            "2026-12-31" to 48, "2028-02-29" to 8, "2028-12-31" to 48,
        )
        for ((date, week) in cases) {
            assertEquals(date, week, Temporal.week48(Instant.parse("${date}T12:00:00Z")))
        }
    }

    @Test
    fun dawnIsWindowOrDawnCategory() {
        assertTrue(Temporal.Context("Dawn", null, null, null, null).dawn)
        assertTrue(Temporal.Context("Morning", 60, true, 1, "winter").dawn)
        assertFalse(Temporal.Context("Night", -300, false, 1, "winter").dawn)
    }
}
